31	/// D₂: 𝟒^{2m} → 𝟒^m × 𝟒^m — de-interlace by position parity.
32	/// Even indices form the first lane, odd indices the second.
33	pub fn d2(seq: &[B4]) -> (Vec<B4>, Vec<B4>) {
34	    let mut even = Vec::with_capacity(seq.len() / 2 + 1);
35	    let mut odd = Vec::with_capacity(seq.len() / 2);
36	    for (i, &v) in seq.iter().enumerate() {
37	        if i % 2 == 0 {
38	            even.push(v);
39	        } else {
40	            odd.push(v);
41	        }
42	    }
43	    (even, odd)
44	}
45	
46	/// J(a,b) = (a, ¬b) — the DQI-conjugate presentation. The first lane is left
47	/// alone, the second lane is Belnap-negated. On the Boolean core this is
48	/// "leave one lane, complement the other"; in the ambient it is richer than
49	/// XOR because N and B are ¬-fixed.
50	pub fn j(a: &[B4], b: &[B4]) -> (Vec<B4>, Vec<B4>) {
51	    (a.to_vec(), b.iter().map(|&v| bnot(v)).collect())
52	}
53	
54	/// Exhaustive proof that r∘¬ ≠ ¬∘r and c∘¬ ≠ ¬∘c exactly on {N,B}.
55	pub fn noncommutation_report() -> String {
56	    let mut out = String::new();
57	    out.push_str("── r∘¬ vs ¬∘r, c∘¬ vs ¬∘c over 𝟒 (exhaustive) ──\n");
58	    let mut r_noncomm = 0usize;
59	    let mut c_noncomm = 0usize;
60	    for v in [B4::N, B4::T, B4::F, B4::B] {
61	        let r_nv = r(bnot(v));
62	        let nr_v = bnot(r(v));
63	        let c_nv = c(bnot(v));
64	        let nc_v = bnot(c(v));
65	        let rd = r_nv != nr_v;
66	        let cd = c_nv != nc_v;
67	        if rd {
68	            r_noncomm += 1;
69	        }
70	        if cd {
71	            c_noncomm += 1;
72	        }
73	        out.push_str(&format!(
74	            "  v={:<2} r(¬v)={:<2} ¬r(v)={:<2} [{}]   c(¬v)={:<2} ¬c(v)={:<2} [{}]\n",
75	            v.name(),
76	            r_nv.name(),
77	            nr_v.name(),
78	            if rd { "≠ NONCOMMUTE" } else { "= commute" },
79	            c_nv.name(),
80	            nc_v.name(),
81	            if cd { "≠ NONCOMMUTE" } else { "= commute" },
82	        ));
83	    }
84	    out.push_str(&format!(
85	        "  r∘¬ ≠ ¬∘r at {} of 4 values (expected exactly 2: N and B) → {}\n",
86	        r_noncomm,
87	        r_noncomm == 2
88	    ));
89	    out.push_str(&format!(
90	        "  c∘¬ ≠ ¬∘c at {} of 4 values (expected exactly 2: N and B) → {}\n",
91	        c_noncomm,
92	        c_noncomm == 2
93	    ));
94	    out
95	}
