97	/// J on the Boolean core {T,F}², and its ambient extension.
98	pub fn j_boolean_core_report() -> String {
99	    let mut out = String::new();
100	    out.push_str("── J(a,b)=(a,¬b) on the Boolean core {T,F}² ──\n");
101	    for a in [B4::T, B4::F] {
102	        for b in [B4::T, B4::F] {
103	            let (ja, jb) = j(&[a], &[b]);
104	            out.push_str(&format!(
105	                "  J({},{}) = ({},{})\n",
106	                a.name(),
107	                b.name(),
108	                ja[0].name(),
109	                jb[0].name()
110	            ));
111	        }
112	    }
113	    out.push_str("  (T,T)↔(T,F), (F,T)↔(F,F): lane 0 fixed, lane 1 complemented — the observed DQI alternation\n");
114	    out.push_str("  ambient: J(a,N)=(a,N), J(a,B)=(a,B) — N,B are ¬-fixed, so the conjugation is richer than XOR with 1010…\n");
115	    out
116	}
