118	/// Recursive ambient de-interlace hierarchy:
119	/// 𝟒^m → (𝟒^{⌈m/2⌉})² → (𝟒^{⌈m/4⌉})⁴ → …
120	pub fn ambient_hierarchy(m: usize) -> String {
121	    let mut out = String::new();
122	    out.push_str(&format!("ambient hierarchy from 𝟒^{}:\n", m));
123	    let mut level = 0usize;
124	    let mut width = m;
125	    let mut lanes = 1usize;
126	    while width > 1 {
127	        out.push_str(&format!("  level {}: 𝟒^{} × {} lanes\n", level, width, lanes));
128	        width = (width + 1) / 2;
129	        lanes *= 2;
130	        level += 1;
131	    }
132	    out.push_str(&format!("  level {}: 𝟒^{} × {} lanes (terminal)\n", level, width, lanes));
133	    out
134	}
