136	/// Per-cell diagnostic on the NEGATED lane (the second lane of D₂): J commutes
137	/// with r and c exactly where the cell is Boolean (T or F); it fails exactly
138	/// where the cell carries N or B. This is the test for genuinely ambient
139	/// structure that a Boolean-first pipeline would have destroyed.
140	pub fn lane_diagnostic(seq: &[B4]) -> String {
141	    let (a, b) = d2(seq);
142	    let mut out = String::new();
143	    out.push_str(&format!(
144	        "D₂(𝟒^{}) → (𝟒^{}, 𝟒^{}); negated-lane commutation diagnostic:\n",
145	        seq.len(),
146	        a.len(),
147	        b.len()
148	    ));
149	    let mut ambient_cells = 0usize;
150	    for (i, &v) in b.iter().enumerate() {
151	        let r_commutes = r(bnot(v)) == bnot(r(v));
152	        let c_commutes = c(bnot(v)) == bnot(c(v));
153	        if !(r_commutes && c_commutes) {
154	            ambient_cells += 1;
155	            out.push_str(&format!(
156	                "  lane-1 cell {} = {} : r(¬{})={} ≠ ¬r({})={}   (ambient: N or B)\n",
157	                i,
158	                v.name(),
159	                v.name(),
160	                r(bnot(v)).name(),
161	                v.name(),
162	                bnot(r(v)).name()
163	            ));
164	        }
165	    }
166	    out.push_str(&format!(
167	        "  {} ambient cell(s) in {} negated-lane cell(s) — commutation fails exactly where N or B sits\n",
168	        ambient_cells,
169	        b.len()
170	    ));
171	    out
172	}
