174	/// Lift a binary string to the 𝟒 Boolean core: '1'→T, '0'→F.
175	pub fn lift_bits(s: &str) -> Vec<B4> {
176	    s.chars()
177	        .filter_map(|ch| match ch {
178	            '1' => Some(B4::T),
179	            '0' => Some(B4::F),
180	            _ => None,
181	        })
182	        .collect()
183	}
184	
185	/// Report for a lifted Boolean numeral: a pure Boolean numeral carries no N/B,
186	/// so its J-conjugate commutes with both retractions everywhere and the
187	/// Boolean retraction is safe. The N/B cells — which only a numeral-first
188	/// pipeline would have erased — are where the ancestral product Φ_N =
189	/// μ(Φ_P,Φ_Q) genuinely resolves to an ambient state.
190	pub fn numeral_report(seq: &[B4]) -> String {
191	    let mut out = String::new();
192	    let ambient = seq.iter().filter(|&&v| v == B4::N || v == B4::B).count();
193	    out.push_str(&format!(
194	        "numeral lift 𝟒^{} (Boolean core): {} ambient (N/B) cell(s)\n",
195	        seq.len(),
196	        ambient
197	    ));
198	    if ambient == 0 {
199	        out.push_str("  no N/B → J∘r = r∘J and J∘c = c∘J everywhere: Boolean retraction is SAFE for this numeral\n");
200	    } else {
201	        out.push_str(&format!(
202	            "  {} ambient cell(s) → Boolean retraction would DESTROY them; keep the 𝟒 presentation until separability\n",
203	            ambient
204	        ));
205	    }
206	    out.push_str(&lane_diagnostic(seq));
207	    out
208	}
