210	/// REPL surface for the ambient de-interlacing correction.
211	pub fn repl_dqi_ambient(args: &[&str]) {
212	    if args.is_empty() || args[0] == "help" {
213	        sprintln!("dqi_ambient — de-interlacing in the four-valued Belnap ambient 𝟒={{N,T,F,B}}");
214	        sprintln!("  dqi_ambient noncommute    exhaustive proof r∘¬≠¬∘r, c∘¬≠¬∘c exactly on {{N,B}}");
215	        sprintln!("  dqi_ambient jcore         J(a,b)=(a,¬b) on the Boolean core vs ambient");
216	        sprintln!("  dqi_ambient hierarchy <m>  recursive 𝟒^m → (𝟒^{{⌈m/2⌉}})² → … ladder (default 862)");
217	        sprintln!("  dqi_ambient diag <N/T/F/B> de-interlace + per-cell commutation diagnostic");
218	        sprintln!("  dqi_ambient numeral <0/1>  lift a Boolean numeral to 𝟒 and run the diagnostic");
219	        sprintln!("  dqi_ambient report        full report");
220	        return;
221	    }
222	    match args[0] {
223	        "noncommute" => sprintln!("{}", noncommutation_report()),
224	        "jcore" => sprintln!("{}", j_boolean_core_report()),
225	        "hierarchy" => {
226	            let m: usize = args.get(1).and_then(|s| s.parse().ok()).unwrap_or(862);
227	            sprintln!("{}", ambient_hierarchy(m));
228	        }
229	        "diag" => {
230	            let s = args.get(1).copied().unwrap_or("");
231	            let seq: Vec<B4> = s
232	                .chars()
233	                .filter_map(|ch| match ch {
234	                    'N' | 'n' => Some(B4::N),
235	                    'T' | 't' => Some(B4::T),
236	                    'F' | 'f' => Some(B4::F),
237	                    'B' | 'b' => Some(B4::B),
238	                    _ => None,
239	                })
240	                .collect();
241	            if seq.is_empty() {
242	                sprintln!("dqi_ambient diag: no 𝟒 values (N/T/F/B) found in input");
243	            } else {
244	                sprintln!("{}", lane_diagnostic(&seq));
245	            }
246	        }
247	        "numeral" => {
248	            let s = args.get(1).copied().unwrap_or("");
249	            let seq = lift_bits(s);
250	            if seq.is_empty() {
251	                sprintln!("dqi_ambient numeral: no binary digits (0/1) found in input");
252	            } else {
253	                sprintln!("{}", numeral_report(&seq));
254	            }
255	        }
256	        "report" => {
257	            sprintln!("{}", noncommutation_report());
258	            sprintln!("{}", j_boolean_core_report());
259	            sprintln!("{}", ambient_hierarchy(862));
260	            sprintln!("{}", crate::belnap::corollary_11_2_report());
261	        }
262	        other => sprintln!("dqi_ambient: unknown subcommand '{}' (try 'dqi_ambient help')", other),
263	    }
264	}
