270	    #[test]
271	    fn negation_commutes_only_on_boolean_core() {
272	        for v in [B4::N, B4::T, B4::F, B4::B] {
273	            let classical = v == B4::T || v == B4::F;
274	            assert_eq!(r(bnot(v)) == bnot(r(v)), classical, "r∘¬ at {}", v.name());
275	            assert_eq!(c(bnot(v)) == bnot(c(v)), classical, "c∘¬ at {}", v.name());
276	        }
277	    }
