279	    #[test]
280	    fn j_is_lane_complement_on_core() {
281	        let (a, b) = j(&[B4::T, B4::F], &[B4::T, B4::T]);
282	        assert_eq!(a, vec![B4::T, B4::F]); // first lane untouched
283	        assert_eq!(b, vec![B4::F, B4::F]); // second lane negated: T→F
284	        let (_, b2) = j(&[B4::F], &[B4::F]);
285	        assert_eq!(b2, vec![B4::T]); // ¬F = T
286	        // J is an involution on both lanes.
287	        let (a, b) = j(&[B4::T], &[B4::F]);
288	        let (ja, jb) = j(&a, &b);
289	        assert_eq!(ja, vec![B4::T]);
290	        assert_eq!(jb, vec![B4::F]);
291	    }
