293	    #[test]
294	    fn j_fixes_ambient_second_lane() {
295	        for x in [B4::N, B4::B] {
296	            let (_, b) = j(&[B4::T], &[x]);
297	            assert_eq!(b[0], x);
298	        }
299	    }
