301	    #[test]
302	    fn d2_preserves_all_cells() {
303	        let seq = [B4::N, B4::T, B4::F, B4::B, B4::T, B4::F];
304	        let (a, b) = d2(&seq);
305	        assert_eq!(a, vec![B4::N, B4::F, B4::T]);
306	        assert_eq!(b, vec![B4::T, B4::B, B4::F]);
307	        assert_eq!(a.len() + b.len(), seq.len());
308	    }
