310	    #[test]
311	    fn inc_has_no_boolean_factorization() {
312	        for v in [B4::N, B4::T, B4::F, B4::B] {
313	            assert_eq!(inc(v), B4::B);
314	            assert_eq!(r(inc(v)), B4::T);
315	            assert_eq!(c(inc(v)), B4::F);
316	        }
