320	/// Four-valued schoolbook multiplication — the ambient composition μ(Φ_P,Φ_Q).
321	///
322	/// Each output column k is a B4 state whose (is_true, is_false) pair is
323	/// (digit, carry_flag): the digit is Σ_{i+j=k} P_i·Q_j + carry, mod 2, and the
324	/// carry flag is whether the column saturated (Σ ≥ 2). So a column with no
325	/// contribution is N, a lone 1 is T, a saturated column with digit 0 is F, and
326	/// a saturated column with digit 1 is B. The carry channel is exactly where
327	/// the two retractions r and c disagree if retraction happens before
328	/// de-interlacing — this is the genuine ambient structure a Boolean product
329	/// destroys. Checked against P=32779, Q=65521: N at one column, B at ten,
330	/// and the is_true (digit) channel recovers N=2147712859 exactly.
331	pub fn b4_schoolbook_mul(a: &[B4], b: &[B4]) -> Vec<B4> {
332	    let n = a.len() + b.len();
333	    let mut out = Vec::with_capacity(n);
334	    let mut carry: u32 = 0;
335	    for k in 0..n {
336	        let mut sum = carry;
337	        for i in 0..=k {
338	            if i >= a.len() {
339	                break;
340	            }
341	            let j = k - i;
342	            if j >= b.len() {
343	                continue;
344	            }
345	            if a[i] == B4::T && b[j] == B4::T {
346	                sum += 1;
347	            }
348	        }
349	        let digit = sum & 1;
350	        let carry_flag = sum >= 2;
351	        out.push(B4::from_wh2(digit == 1, carry_flag));
352	        carry = sum >> 1;
353	    }
354	    out
355	}
356	
357	/// The digit channel of a four-valued product: is_true per column. This is the
358	/// Boolean retraction that recovers the true product — r at B cells, c at N
359	/// cells, i.e. the digit bit itself, which is what a Boolean product keeps and
360	/// what r-alone or c-alone both get wrong (checked: r gives a wrong high bit,
361	/// c collapses the carry tail to zeros).
362	pub fn b4_digit_channel(prod: &[B4]) -> Vec<B4> {
363	    prod.iter()
364	        .map(|&v| if v.to_wh2().0 { B4::T } else { B4::F })
365	        .collect()
366	}
367	
368	/// Census the ambient cells of a four-valued product: counts and positions of
369	/// N and B columns (the carry structure).
370	pub fn b4_ambient_census(prod: &[B4]) -> (usize, usize, Vec<usize>) {
371	    let mut n_count = 0usize;
372	    let mut b_count = 0usize;
373	    let mut positions = Vec::new();
374	    for (i, &v) in prod.iter().enumerate() {
375	        if v == B4::N {
376	            n_count += 1;
377	            positions.push(i);
378	        } else if v == B4::B {
379	            b_count += 1;
380	            positions.push(i);
381	        }
382	    }
383	    (n_count, b_count, positions)
384	}
385	
386	/// De-interlace a four-valued product stream, J-conjugate, and run the
387	/// noncommutation diagnostic. Returns the ambient-cell census of the negated
388	/// lane — the carry structure of μ(Φ_P,Φ_Q) seen through D₂∘J.
389	pub fn ambient_product_report(prod: &[B4]) -> String {
390	    let (a0, a1) = d2(prod);
391	    let (_ja0, ja1) = j(&a0, &a1);
392	    let mut out = String::new();
393	    out.push_str(&format!(
394	        "μ(Φ_P,Φ_Q) as 𝟒^{}: D₂ → (𝟒^{}, 𝟒^{}); J negates lane 1\n",
395	        prod.len(),
396	        a0.len(),
397	        a1.len()
398	    ));
399	    let mut ambient = 0usize;
400	    for (i, &v) in ja1.iter().enumerate() {
401	        let r_comm = r(bnot(v)) == bnot(r(v));
402	        let c_comm = c(bnot(v)) == bnot(c(v));
403	        if !(r_comm && c_comm) {
404	            ambient += 1;
405	            out.push_str(&format!(
406	                "  lane-1 cell {} = {} : ambient (r∘¬≠¬∘r, c∘¬≠¬∘c)\n",
407	                i,
408	                v.name()
409	            ));
410	        }
411	    }
412	    out.push_str(&format!("  {} ambient cell(s) in {} negated-lane cell(s)\n", ambient, ja1.len()));
413	    out
414	}
