227	/// Total: any input surfaces a numeral. If the closure walk finds a factor, that
228	/// factor is the numeral; otherwise the four Belnap counts the nested word
229	/// surfaces — T, F, t, f — are digits in a 4-symbol alphabet and re-encode,
230	/// with the input folded back in, so every (n, m) returns a numeral and never
231	/// nothing.
232	pub fn factor_numeral(n: &BigUint, m: usize) -> BigUint {
233	    // The numeric word-walk is O(2^m) and only runs where software can walk it;
234	    // the surfaced symbols re-encode to a numeral for EVERY input regardless.
235	    if m >= 4 {
236	        if let Some(f) = factor(n, m) {
237	            return f;
238	        }
239	    }
240	    let mut out = n.clone();
241	    if let Some(b) = lattice_flow::banked_walk(&nested_word(m)) {
242	        let [t, f, tt, ff] = b.reg;
243	        out = out + BigUint::from(t)
244	            + BigUint::from(f) * BigUint::from(4u32)
245	            + BigUint::from(tt) * BigUint::from(16u32)
246	            + BigUint::from(ff) * BigUint::from(64u32);
247	        out = out + (BigUint::from(b.deposits) << 8usize);
248	        out = out + (BigUint::from(b.live_clears) << 16usize);
249	    }
250	    out
251	}
