371	/// The closure-height walk, arbitrary precision — the m<=60 floor eliminated.
372	///
373	/// The kernel is a trilattice tiling the horn torus that is the modulus: the
374	/// four cosets {1, 3, -1, -3} mod 2^m are the four tiles, and the 9-step orbit
375	/// winds the torus. The u64 cap in the GPU closure kernel was a register width,
376	/// not a property of the tiling — the tiling is width-free. Here P, Q and the
377	/// closure height h are BigUint/BigInt, so the width m is limited only by the
378	/// O(2^m) position count, never by a 64-bit limb.
379	///
380	/// h = (P·Q - N)/2^m is seeded once and updated by the exact add
381	/// h' = h + d·P - a·Q2, where a = 9P >> m and d = (9Q2 - Q) >> m are the wrap
382	/// digits. Sealing on h == 0 is exactly P·Q == N. Verified against the GPU
383	/// kernel's own update, and verified at m=66 (past u64) in tests.
384	pub fn closure_height_walk(n: &BigUint, m: usize, max_steps: usize) -> Option<BigUint> {
385	    if m < 4 { return None; }
386	    let two_m = BigUint::one() << m;
387	    let mask = &two_m - BigUint::one();
388	    let lead = BigUint::one() << (m - 1);
389	    let nine = BigUint::from(9u32);
390	    let inv9 = big_inv_pow2(&nine, m);
391	    let nm = n & &mask;
392	    let reps = [
393	        BigUint::one(),
394	        BigUint::from(3u32),
395	        &two_m - BigUint::one(),
396	        &two_m - BigUint::from(3u32),
397	    ];
398	    let positions = 1usize.checked_shl((m - 3) as u32).unwrap_or(usize::MAX);
399	    let steps = core::cmp::min(positions, max_steps);
400	    for rep in &reps {
401	        let mut p = rep % &two_m;
402	        let mut q = (&nm * big_inv_pow2(&p, m)) & &mask;
403	        // Seed h = (p·q - n)/2^m, signed and exact (p·q ≡ n mod 2^m).
404	        let mut h: BigInt = BigInt::from_biguint(Sign::Plus, &p * &q)
405	            - BigInt::from_biguint(Sign::Plus, n.clone());
406	        h >>= m;
407	        for _ in 0..steps {
408	            if h.is_zero() && p >= lead && q >= lead {
409	                return Some(if p < q { p } else { q });
410	            }
411	            let nine_p = &p * &nine;
412	            let a = &nine_p >> m;
413	            let p2 = &nine_p & &mask;
414	            let q2 = (&q * &inv9) & &mask;
415	            let d = ((&q2 * &nine) - &q) >> m;
416	            h = h + BigInt::from_biguint(Sign::Plus, &d * &p)
417	                - BigInt::from_biguint(Sign::Plus, &a * &q2);
418	            p = p2;
419	            q = q2;
420	        }
421	    }
422	    None
423	}
