468	        assert!(n_count + b_count > 0, "carry structure must be nonempty (ambient cells)");
469	    }
470	
471	    #[test]
472	    fn ambient_factor_matches_walk() {
473	        // Same factors as the Boolean walk, now with the ambient product wired in.
474	        assert_eq!(factor_ambient(&bi("2147712859"), 16).unwrap().0, bi("32779"));
475	        assert_eq!(factor_ambient(&bi("8796158033869"), 22).unwrap().0, bi("2097169"));
476	        assert_eq!(factor_ambient(&bi("140737614184421"), 24).unwrap().0, bi("8388617"));
477	    }
478	
479	    #[test]
480	    fn nested_noop_surfaces_work_when_sequenced() {
481	        // The ∈^d…∋^d frame stack is inert alone (deposits 0, VACUOUS, final N);
482	        // the same frames nested with the working sequence ≻⋈⊤≻⋈⊥≺⋈⊞⊙ surface
483	        // the work as the four cosets. Checked by the kernel directly.
484	        let d = 10usize;
485	        let mut bare = String::from("⊢");
486	        for _ in 0..d { bare.push('∈'); }
487	        for _ in 0..d { bare.push('∋'); }
488	        bare.push_str("⊡⊣");
489	        let b0 = imasm_core::lattice_flow::banked_walk(&bare).unwrap();
490	        assert_eq!(b0.deposits, 0, "bare frame stack must be inert");
491	        assert!(!b0.holds(), "bare frame stack holds nothing");
492	
493	        let w = nested_word(d + 3);
494	        let b1 = imasm_core::lattice_flow::banked_walk(&w).unwrap();
495	        assert_eq!(b1.deposits, 3, "nested with work must surface the deposits");
496	        assert_eq!(b1.live_clears, 1, "one live clear survives by banking");
497	        assert!(b1.exposed.is_empty(), "nothing exposed");
498	        assert!(b1.holds(), "nested work holds");
499	        // The four surviving Belnap states are the four cosets {1,3,-1,-3}.
500	        assert_eq!(b1.reg, [1, 1, 1, 1], "register holds all four cosets");
501	    }
502	
503	    #[test]
504	    fn closure_height_walk_past_u64_floor() {
505	        // m=66 factors are past the u64 wall (P, Q each 66 bits). The arbitrary-
506	        // precision closure-height walk must find the factor; the u64 GPU kernel
507	        // would refuse m=66 outright. P = 9^26 mod 2^66 has its lead bit set and
508	        // sits 26 steps from the coset-1 seed; Q = 2^65 + 3.
509	        let m = 66usize;
510	        let two_m = BigUint::one() << m;
511	        let mask = &two_m - BigUint::one();
512	        let mut p = BigUint::one();
513	        for _ in 0..26 { p = (p * BigUint::from(9u32)) & &mask; }
514	        let q = (BigUint::one() << 65) + BigUint::from(3u32);
515	        let n = &p * &q;
516	        let f = closure_height_walk(&n, m, 64).unwrap();
517	        assert!(f == p || f == q, "must recover one factor at m=66");
518	        assert_eq!(&f * (&n / &f), n, "factor must close N");
519	        // m=82 (far past u64): construct a near-seed factor in coset 1.
520	        let m2 = 82usize;
521	        let two_m2 = BigUint::one() << m2;
522	        let mask2 = &two_m2 - BigUint::one();
523	        let lead2 = BigUint::one() << (m2 - 1);
524	        let (mut p2, mut k2) = (BigUint::one(), 0usize);
525	        while p2 < lead2 && k2 < 200 { p2 = (p2 * BigUint::from(9u32)) & &mask2; k2 += 1; }
526	        assert!(p2 >= lead2, "must find a lead-bit-set coset-1 point at m=82");
527	        let q2 = (BigUint::one() << 81) + BigUint::from(3u32);
528	        let n2 = &p2 * &q2;
529	        let f2 = closure_height_walk(&n2, m2, 256).unwrap();
530	        assert!(f2 == p2 || f2 == q2, "must recover one factor at m=82");
531	        assert_eq!(&f2 * (&n2 / &f2), n2, "m=82 factor must close N");
532	    }
533	
534	    #[test]
535	    fn symbolic_production_is_search_free() {
536	        // factor_symbolic must run with no numeric walk and report the four
537	        // cosets for ANY width, including widths beyond the m<=26 walk floor.
538	        let out = factor_symbolic(&bi("2147712859"), 16);
539	        assert!(out.contains("no search"), "must state search-free");
540	        assert!(out.contains("65535") && out.contains("65533"), "must list -1,-3 residues");
541	        let wide = factor_symbolic(&bi("2147712859"), 431);
542	        assert!(wide.contains("depth d=428"), "must nest at d=m-3 for wide m");
543	    }
544	
545	    #[test]
546	    fn factors_far_apart() {
547	        // 32779 x 65521 (ratio 2.0), 2097169 x 4194301, 8388617 x 16777213
548	        assert_eq!(factor(&bi("2147712859"), 16).unwrap(), bi("32779"));
549	        assert_eq!(factor(&bi("8796158033869"), 22).unwrap(), bi("2097169"));
550	        assert_eq!(factor(&bi("140737614184421"), 24).unwrap(), bi("8388617"));
551	    }
552	}
