1	//! Native IMASM-Numeral Mapping — ob3ect-backed kernel tool.
2	//!
3	//! The artifact "Native IMASM-Numeral Mapping" is a verified ob3ect whose
4	//! glyph word `⊢⊣≻⋈∈⊤⊥⊞∋⊙≺⊡⋈⊣` maps a number into the Grammar through its
5	//! parity grade. Its boundary is the Z2 topological invariant, parity, the
6	//! one bit that cannot deform to zero without crossing a phase boundary. The
7	//! marks are numeral roles:
8	//!
9	//!   ⊢ VINIT   void_numeral          the uninitialized value
10	//!   ⊣ TANCH   topological_boundary  the closed numeral system
11	//!   ≻ AFWD    increment_magnitude   one step up in magnitude
12	//!   ⋈ CLINK   digit_composition     chain a digit onto the numeral
13	//!   ∈ FSPLIT  parity_branch         split on parity, even arm and odd arm
14	//!   ⊤ EVALT   even_parity           the digit is even (0)
15	//!   ⊥ EVALF   odd_parity            the digit is odd (1)
16	//!   ⊞ ENGAGR  chiral_superposition  both parities held
17	//!   ∋ FFUSE   stoichiometric_rejoin the arms rejoin
18	//!   ⊙ IMSCRIB critical_state        the value recognizes itself
19	//!   ≺ AREV    decrement_magnitude   one step down
20	//!   ⊡ IFIX    immutable_record      the Z2 fixation, the value made permanent
21	//!
22	//! Why this and not the hex-nibble encoding. prime_winding maps a number by
23	//! looking each hex digit up in a fixed table, and its own header records that
24	//! this reads only a bounded local pattern in the digits: it went T the moment
25	//! any nibble was 8 or higher, tracking no global fact. This mapping is built
26	//! from the Z2 parity grade instead: a number is encoded bit by bit, each bit
27	//! its own parity branch, even on the ⊤ arm and odd on the ⊥ arm, so the whole
28	//! binary expansion is carried as a chain of closed parity branches. The
29	//! encoding is exact and reversible, and distinct numbers give distinct words.
30	//!
31	//! The raw blueprint word clears its parity superposition at the ≺ decrement
32	//! with nothing banked, which the ob3ect's own banked check flags. The
33	//! per-number encoding here is built to hold instead: each bit's branch opens,
34	//! works, and fuses before the next, so no count is left in the open.
35	//!
36	//! Subcommands:
37	//!   native_numeral word         the canonical glyph word and its marks
38	//!   native_numeral encode <n>   map n to its native parity-graded word
39	//!   native_numeral help         list subcommands
40	
41	use alloc::string::String;
42	use alloc::format;
43	use alloc::vec::Vec;
44	use num_bigint::{BigUint, BigInt};
45	use num_traits::Zero;
46	use imasm_core::lattice_flow::{tri_ancestral_word_verdict, cycle_landings};
47	
48	/// The ob3ect's own fixed reference word.
49	pub const WORD: &str = "⊢⊣≻⋈∈⊤⊥⊞∋⊙≺⊡⋈⊣";
50	pub const PERIOD: usize = 14;
51	pub const ARTIFACT: &str = "Native IMASM-Numeral Mapping";
52	
53	/// Map n to its native parity-graded IMASM word. Bits are read low to high;
54	/// each bit is one closed parity branch, ∈ then its parity arm then ∋, so the
55	/// branch works and fuses before the next bit opens, and nothing is left in
56	/// the open for a later clear. The magnitude step ≻ precedes each branch, the
57	/// value is recognized at ⊙ and fixed at ⊡, and the whole is bounded by ⊢ and
58	/// ⊣. n = 0 is the void numeral, ⊢⊙⊡⊣, a fixed empty magnitude.
59	pub fn encode(n_str: &str) -> String {
60	    let n: BigUint = match n_str.trim().parse() {
61	        Ok(v) => v,
62	        Err(_) => return String::new(),
63	    };
64	    encode_biguint(&n)
65	}
66	
67	/// The same word encode produces, taking the BigUint directly rather than
68	/// its decimal string. encode itself already does its real work this way,
69	/// parsing once and calling straight into to_bits_low_first -- this just
70	/// gives that path its own name so a caller who already has the BigUint
71	/// (every word-native operation in this file does) never has to pay for
72	/// converting it to decimal and re-parsing it just to read its own bits.
73	fn encode_biguint(n: &BigUint) -> String {
74	    let mut w = String::new();
75	    w.push('⊢');
76	    if n.is_zero() {
77	        w.push('⊙');
78	        w.push('⊡');
79	        w.push('⊣');
80	        return w;
81	    }
82	    let bits = to_bits_low_first(n);
83	    for b in bits.iter() {
84	        w.push('≻');            // increment_magnitude: advance one position
85	        w.push('⋈');            // digit_composition: chain this digit on
86	        w.push('∈');            // parity_branch
87	        w.push(if *b { '⊥' } else { '⊤' }); // odd → ⊥, even → ⊤
88	        w.push('∋');            // stoichiometric_rejoin
89	    }
90	    w.push('⊙');                // critical_state: recognize the value
91	    w.push('⊡');                // immutable_record: the Z2 fixation
92	    w.push('⊣');                // topological_boundary
93	    w
94	}
