96	/// The exact inverse of `encode`: reads a native-numeral word back to its
97	/// integer. None for anything that isn't a well-formed encode() output —
98	/// callers that also accept plain decimal strings should try that first and
99	/// fall back to this, not the reverse, since a decimal string is never
100	/// mistaken for a word but a malformed word could in principle be mistaken
101	/// for garbage either way.
102	pub fn decode(word: &str) -> Option<BigUint> {
103	    let c: alloc::vec::Vec<char> = word.chars().collect();
104	    if c.first() != Some(&'⊢') {
105	        return None;
106	    }
107	    if c.len() == 4 && c[1] == '⊙' && c[2] == '⊡' && c[3] == '⊣' {
108	        return Some(BigUint::zero());
109	    }
110	    if c.len() < 4 || c[c.len() - 3] != '⊙' || c[c.len() - 2] != '⊡' || c[c.len() - 1] != '⊣' {
111	        return None;
112	    }
113	    let body = &c[1..c.len() - 3];
114	    if body.is_empty() || body.len() % 5 != 0 {
115	        return None;
116	    }
117	    let mut n = BigUint::zero();
118	    let two = BigUint::from(2u32);
119	    for (i, cell) in body.chunks(5).enumerate() {
120	        if cell[0] != '≻' || cell[1] != '⋈' || cell[2] != '∈' || cell[4] != '∋' {
121	            return None;
122	        }
123	        let bit = match cell[3] {
124	            '⊥' => true,
125	            '⊤' => false,
126	            _ => return None,
127	        };
128	        if bit {
129	            n += two.pow(i as u32);
130	        }
131	    }
132	    Some(n)
133	}
