135	/// Halve an even number by deleting one bit-block from its own word, not by
136	/// dividing. `encode` writes bits least-significant-first, so the block
137	/// right after `⊢` is n's own parity: `⊤` there means even. Every other
138	/// block already holds bit 1, bit 2, ... of n in place, which is exactly
139	/// bit 0, bit 1, ... of n/2 — dropping the first block costs nothing else,
140	/// no bit anywhere else has to move. `decode` on what's left is n/2. There
141	/// is no `/` or `%` in this function; the division already happened in the
142	/// word's own layout, this only reads it off. None for odd n, since this
143	/// method has nothing to drop that stays exact.
144	// ═══════════════════════════════════════════════════════════════════════
145	// The bits_* functions below are the real core: every one takes and
146	// returns Vec<bool> (a word's own bits, least-significant first), and none
147	// of them ever touches BigUint. A computation built from these -- gcd,
148	// modular exponentiation, anything -- can run its entire loop without
149	// converting back and forth at each step; only the outermost call needs to
150	// enter and leave bit form at all. The pub fn wrappers below them are the
151	// BigUint-facing convenience layer: encode once on the way in, decode once
152	// on the way out, never in between.
153	// ═══════════════════════════════════════════════════════════════════════
154	
155	// The trilattice's own Reg16_3 (SixteenThreeTrilattice.lean) already makes
156	// this move at a small scale: four lanes packed into one register instead
157	// of four separate bools, because a register is what a real machine
158	// reads and moves as a unit, not a bag of individually-boxed bits. The
159	// bits_* functions below make the same move at the scale arithmetic
160	// actually needs: sixty-four lanes packed into one u64 limb, least-
161	// significant limb first, bit i of limb i/64 being value-bit i overall.
162	// The full-adder and full-subtractor logic is unchanged -- it now runs on
163	// whole 64-bit words via the CPU's own carry/borrow flag instead of one
164	// hand-matched bool at a time, the same ripple-carry shape real bignum
165	// arithmetic has always used, just no longer simulated bit by bit in a
166	// heap-allocated Vec<bool>.
167	
168	/// Drop trailing (most-significant) all-zero limbs, so limb vectors built
169	/// by different paths compare and add correctly regardless of how many
170	/// spare zero limbs they happened to pick up.
171	fn limbs_trim(mut v: alloc::vec::Vec<u64>) -> alloc::vec::Vec<u64> {
172	    while v.last() == Some(&0) { v.pop(); }
173	    v
174	}
175	
176	/// Bit i of a limb vector, least-significant first, 0 past the end.
177	fn limb_bit(limbs: &[u64], i: usize) -> bool {
178	    limbs.get(i / 64).map(|l| (l >> (i % 64)) & 1 == 1).unwrap_or(false)
179	}
180	
181	/// Halve, on limbs alone: shift every limb right by one, carrying the
182	/// bottom bit of each limb into the top bit of the one below it. None if
183	/// the very lowest bit (bit 0 of limb 0) is set -- odd, nothing exact to
184	/// drop.
185	fn bits_halve(limbs: &[u64]) -> Option<alloc::vec::Vec<u64>> {
186	    if limbs.is_empty() { return Some(alloc::vec::Vec::new()); }
187	    if limbs[0] & 1 == 1 { return None; }
188	    let mut out = alloc::vec::Vec::with_capacity(limbs.len());
189	    for i in 0..limbs.len() {
190	        let hi_bit = if i + 1 < limbs.len() { (limbs[i + 1] & 1) << 63 } else { 0 };
191	        out.push((limbs[i] >> 1) | hi_bit);
192	    }
193	    Some(limbs_trim(out))
194	}
195	
196	/// Double, on limbs alone: shift every limb left by one, carrying the top
197	/// bit of each limb into the bottom bit of the next, appending a new limb
198	/// only if the very last carry overflows past the top.
199	fn bits_double(limbs: &[u64]) -> alloc::vec::Vec<u64> {
200	    let mut out = alloc::vec::Vec::with_capacity(limbs.len() + 1);
201	    let mut carry: u64 = 0;
202	    for &limb in limbs {
203	        out.push((limb << 1) | carry);
204	        carry = limb >> 63;
205	    }
206	    if carry != 0 { out.push(carry); }
207	    out
208	}
209	
210	/// Shift left by any sub-limb amount s (0 <= s < 64) in one pass --
211	/// bits_double generalized from "shift by exactly one" to "shift by s",
212	/// the same carry-between-limbs shape. Needed to normalize a divisor's
213	/// leading limb for Knuth's long division below.
214	fn shift_left_bits(limbs: &[u64], s: u32) -> alloc::vec::Vec<u64> {
215	    if s == 0 { return limbs.to_vec(); }
216	    let mut out = alloc::vec::Vec::with_capacity(limbs.len() + 1);
217	    let mut carry: u64 = 0;
218	    for &limb in limbs {
219	        out.push((limb << s) | carry);
220	        carry = limb >> (64 - s);
221	    }
222	    if carry != 0 { out.push(carry); }
223	    out
224	}
225	
226	/// Shift right by any sub-limb amount s (0 <= s < 64), the mirror of
227	/// shift_left_bits: each limb takes its own high bits plus the low bits
228	/// carried down from the limb above it.
229	pub(crate) fn shift_right_bits(limbs: &[u64], s: u32) -> alloc::vec::Vec<u64> {
230	    if s == 0 { return limbs_trim(limbs.to_vec()); }
231	    let mut out = alloc::vec::Vec::with_capacity(limbs.len());
232	    for i in 0..limbs.len() {
233	        let lo = limbs[i] >> s;
234	        let hi = if i + 1 < limbs.len() { limbs[i + 1] << (64 - s) } else { 0 };
235	        out.push(lo | hi);
236	    }
237	    limbs_trim(out)
238	}
239	
240	/// a - b, on limbs alone, ripple-borrow across native 64-bit words: the
241	/// same three-input borrow logic a hardware subtractor uses, applied
242	/// sixty-four bits at a time via the CPU's own overflow flag instead of a
243	/// hand-written truth table per bit. None if a < b.
244	fn bits_subtract(a: &[u64], b: &[u64]) -> Option<alloc::vec::Vec<u64>> {
245	    let n = a.len().max(b.len());
246	    let mut result = alloc::vec::Vec::with_capacity(n);
247	    let mut borrow = false;
248	    for i in 0..n {
249	        let x = *a.get(i).unwrap_or(&0);
250	        let y = *b.get(i).unwrap_or(&0);
251	        let (r1, b1) = x.overflowing_sub(y);
252	        let (r2, b2) = r1.overflowing_sub(borrow as u64);
253	        result.push(r2);
254	        borrow = b1 || b2;
255	    }
256	    if borrow { return None; }
257	    Some(limbs_trim(result))
258	}
259	
260	/// a + b, on limbs alone, ripple-carry across native 64-bit words, the
261	/// same shape as bits_subtract with the CPU's carry flag in place of its
262	/// borrow flag.
263	fn bits_add(a: &[u64], b: &[u64]) -> alloc::vec::Vec<u64> {
264	    let n = a.len().max(b.len());
265	    let mut result = alloc::vec::Vec::with_capacity(n + 1);
266	    let mut carry = false;
267	    for i in 0..n {
268	        let x = *a.get(i).unwrap_or(&0);
269	        let y = *b.get(i).unwrap_or(&0);
270	        let (r1, c1) = x.overflowing_add(y);
271	        let (r2, c2) = r1.overflowing_add(carry as u64);
272	        result.push(r2);
273	        carry = c1 || c2;
274	    }
275	    if carry { result.push(1); }
276	    limbs_trim(result)
277	}
278	
279	/// a >= b, on limbs alone, most significant limb first. A limb missing on
280	/// the shorter side reads as 0. Ordering isn't one of the four arithmetic
281	/// operations and this is the one place any comparison happens in the
282	/// operations below -- a direct limb compare, not a BigUint `>=` in
283	/// disguise.
284	fn bits_ge(a: &[u64], b: &[u64]) -> bool {
285	    let n = a.len().max(b.len());
286	    for i in (0..n).rev() {
287	        let x = *a.get(i).unwrap_or(&0);
288	        let y = *b.get(i).unwrap_or(&0);
289	        if x != y { return x > y; }
290	    }
291	    true
292	}
293	
294	/// a == b, on limbs alone, safe against the two sides having different
295	/// lengths (a subtraction or addition result can carry trailing zero
296	/// limbs a trimmed word never would) since bits_ge already treats a
297	/// missing limb as 0 on either side.
298	fn bits_eq(a: &[u64], b: &[u64]) -> bool {
299	    bits_ge(a, b) && bits_ge(b, a)
300	}
301	
302	/// a > b, on limbs alone.
303	fn bits_gt(a: &[u64], b: &[u64]) -> bool {
304	    bits_ge(a, b) && !bits_ge(b, a)
305	}
306	
307	/// a * b, on limbs alone, shift-and-add: walk b's bits low to high (via
308	/// limb_bit, not a whole extra unpacking pass), add in a's current running
309	/// double wherever the bit is set, doubling either way. Each bits_add and
310	/// bits_double call now moves whole limbs, not one bool at a time -- the
311	/// same shift-and-add shape, at native word width. O(bits(a)*bits(b)); the
312	/// base case Karatsuba multiplication below falls back to under its own
313	/// size threshold, where the recursion's own overhead costs more than it
314	/// saves.
315	fn bits_multiply_schoolbook(a: &[u64], b: &[u64]) -> alloc::vec::Vec<u64> {
316	    let mut acc: alloc::vec::Vec<u64> = alloc::vec::Vec::new();
317	    let mut shifted = a.to_vec();
318	    for i in 0..b.len() * 64 {
319	        if limb_bit(b, i) { acc = bits_add(&acc, &shifted); }
320	        shifted = bits_double(&shifted);
321	    }
322	    acc
323	}
324	
325	/// Split a limb vector at limb index m: the low m limbs, and everything
326	/// from m up (empty if the vector is already that short).
327	fn split_at_limb(limbs: &[u64], m: usize) -> (alloc::vec::Vec<u64>, alloc::vec::Vec<u64>) {
328	    if limbs.len() <= m {
329	        (limbs.to_vec(), alloc::vec::Vec::new())
330	    } else {
331	        (limbs[..m].to_vec(), limbs[m..].to_vec())
332	    }
333	}
334	
335	/// Multiply by 2^(64*m): prepend m zero limbs. The cheap way to multiply
336	/// by a power of the limb base, no arithmetic needed.
337	fn shift_limbs(limbs: &[u64], m: usize) -> alloc::vec::Vec<u64> {
338	    if limbs.is_empty() { return alloc::vec::Vec::new(); }
339	    let mut out = alloc::vec::Vec::with_capacity(limbs.len() + m);
340	    out.resize(m, 0u64);
341	    out.extend_from_slice(limbs);
342	    out
343	}
344	
345	/// Below this many limbs (2048 bits), the recursion's own bookkeeping
346	/// (splits, extra adds and subtracts, three separate recursive calls)
347	/// costs more than the schoolbook walk it would replace. Above it,
348	/// Karatsuba wins by more each time the input doubles.
349	const KARATSUBA_THRESHOLD_LIMBS: usize = 32;
350	
351	/// a * b, on limbs alone, by Karatsuba's own trick: split each operand
352	/// into a high and low half by limb count, a = a1*B + a0 and b = b1*B +
353	/// b0 for B = 2^(64m), so a*b = a1*b1*B^2 + (a0*b1 + a1*b0)*B + a0*b0.
354	/// The cross term a0*b1 + a1*b0 is read off a sum instead of computed
355	/// directly: (a0+a1)*(b0+b1) - a0*b0 - a1*b1 expands to exactly that
356	/// cross term, since the two squared-half products cancel out of the
357	/// expansion. That means only three recursive products are needed --
358	/// a0*b0, a1*b1, and (a0+a1)*(b0+b1) -- where a schoolbook split would
359	/// need four (a0*b0, a0*b1, a1*b0, a1*b1). That drop from four products
360	/// to three, applied recursively, is what turns O(n^2) into roughly
361	/// O(n^1.585): the same "read a combined quantity off a sum instead of
362	/// computing its pieces separately" shape as bits_add/bits_subtract
363	/// reading a carry or borrow off the CPU's own flag instead of a table.
364	/// Both subtractions below are proven safe by that same algebra -- the
365	/// cross term a0*b1 + a1*b0 is a sum of two nonnegative products, so the
366	/// sum-of-sums it is read from can never be smaller than either piece
367	/// being subtracted out, not merely assumed nonnegative.
368	fn bits_multiply(a: &[u64], b: &[u64]) -> alloc::vec::Vec<u64> {
369	    if a.is_empty() || b.is_empty() { return alloc::vec::Vec::new(); }
370	    let n = a.len().max(b.len());
371	    if n <= KARATSUBA_THRESHOLD_LIMBS {
372	        return bits_multiply_schoolbook(a, b);
373	    }
374	    let m = n / 2;
375	    let (a0, a1) = split_at_limb(a, m);
376	    let (b0, b1) = split_at_limb(b, m);
377	
378	    let z0 = bits_multiply(&a0, &b0);
379	    let z2 = bits_multiply(&a1, &b1);
380	    let a_sum = bits_add(&a0, &a1);
381	    let b_sum = bits_add(&b0, &b1);
382	    let z1_full = bits_multiply(&a_sum, &b_sum);
383	    let z1 = bits_subtract(&bits_subtract(&z1_full, &z0).unwrap(), &z2).unwrap();
384	
385	    let result = bits_add(&bits_add(&shift_limbs(&z2, 2 * m), &shift_limbs(&z1, m)), &z0);
386	    limbs_trim(result)
387	}
