426	/// a divided by m and the remainder, on limbs alone, by long division: walk
427	/// a's bits from the top down (via limb_bit), double the running remainder
428	/// to shift in the next dividend bit, and subtract m back out (marking
429	/// that quotient bit) wherever the remainder has grown at least as large
430	/// as m. Every step moves whole limbs; only the caller decides whether and
431	/// when to turn either result back into a BigUint.
432	fn bits_divmod(a: &[u64], m: &[u64]) -> (alloc::vec::Vec<u64>, alloc::vec::Vec<u64>) {
433	    let nbits = a.len() * 64;
434	    let mut remainder: alloc::vec::Vec<u64> = alloc::vec::Vec::new();
435	    let mut quotient_bits = alloc::vec![false; nbits];
436	    for i in (0..nbits).rev() {
437	        remainder = bits_double(&remainder);
438	        if limb_bit(a, i) {
439	            remainder = bits_add(&remainder, &[1u64]);
440	        }
441	        if bits_ge(&remainder, m) {
442	            remainder = bits_subtract(&remainder, m).unwrap();
443	            quotient_bits[i] = true;
444	        }
445	    }
446	    let mut q: alloc::vec::Vec<u64> = alloc::vec::Vec::with_capacity(nbits / 64 + 1);
447	    for (i, &bit) in quotient_bits.iter().enumerate() {
448	        if bit {
449	            let li = i / 64;
450	            while q.len() <= li { q.push(0); }
451	            q[li] |= 1u64 << (i % 64);
452	        }
453	    }
454	    (limbs_trim(q), remainder)
455	}
456	
457	/// Long division, limb at a time (Knuth's Algorithm D, the shape every
458	/// real bignum library uses): the same long division bits_divmod already
459	/// does, but estimating each quotient LIMB directly from the divisor's
460	/// own top two limbs via one hardware u128 division, instead of testing
461	/// and shifting one bit at a time. bits_divmod does 64 times as many
462	/// steps as this for the same inputs; this is the general-divisor
463	/// counterpart to divmod_small_on_limbs's own limb-at-a-time gain over
464	/// bit-at-a-time, extended to a divisor of any size rather than one
465	/// known to fit in a word. Falls back to divmod_small_on_limbs directly
466	/// when the divisor is already single-limb, since that path needs no
467	/// estimation at all.
468	///
469	/// Normalizes first (shifts both operands left so the divisor's top limb
470	/// has its high bit set -- multiplying numerator and denominator by the
471	/// same power of two changes neither the quotient nor, once shifted back
472	/// down, the remainder) so the two-limb quotient estimate is never off
473	/// by more than 1 from the true digit, per Knuth's own proof; the
474	/// estimate is corrected against the divisor's second limb before ever
475	/// being used, and the multiply-and-subtract step's own borrow (the one
476	/// case Knuth's proof still allows through) is caught by an explicit
477	/// add-back, not assumed away.
478	fn bits_divmod_knuth(a: &[u64], b: &[u64]) -> (alloc::vec::Vec<u64>, alloc::vec::Vec<u64>) {
479	    let b = limbs_trim(b.to_vec());
480	    let a = limbs_trim(a.to_vec());
481	    if b.len() <= 1 {
482	        let divisor = b.first().copied().unwrap_or(0);
483	        let (q, r) = divmod_small_on_limbs(&a, divisor);
484	        return (q, if r == 0 { alloc::vec::Vec::new() } else { alloc::vec![r] });
485	    }
486	    if a.len() < b.len() {
487	        return (alloc::vec::Vec::new(), a);
488	    }
489	
490	    let n = b.len();
491	    let shift = b[n - 1].leading_zeros();
492	    let bn = shift_left_bits(&b, shift); // still n limbs: leading_zeros guarantees no overflow into a new one
493	    let mut un = shift_left_bits(&a, shift);
494	    if un.len() == a.len() { un.push(0); } // guarantee exactly one spare limb above the dividend for the algorithm's own window, whether or not the shift itself produced one
495	    let qlen = un.len() - n;
496	    let mut q = alloc::vec![0u64; qlen];
497	    let v1 = bn[n - 1] as u128;
498	    let v0 = bn[n - 2] as u128;
499	    const BASE: u128 = 1u128 << 64;
500	
501	    for j in (0..qlen).rev() {
502	        let u2 = un[j + n] as u128;
503	        let u1 = un[j + n - 1] as u128;
504	        let u0 = un[j + n - 2] as u128;
505	        let numer = (u2 << 64) | u1;
506	        let mut qhat = numer / v1;
507	        let mut rhat = numer % v1;
508	        if qhat >= BASE {
509	            qhat = BASE - 1;
510	            rhat = numer - qhat * v1;
511	        }
512	        while rhat < BASE && qhat * v0 > (rhat << 64) + u0 {
513	            qhat -= 1;
514	            rhat += v1;
515	        }
516	
517	        // Multiply the trial digit by the whole (normalized) divisor and
518	        // subtract it from the current window, ripple-borrowing across
519	        // limbs the same way bits_subtract does.
520	        let mut carry: u128 = 0;
521	        let mut borrow = false;
522	        for i in 0..n {
523	            let p = qhat * bn[i] as u128 + carry;
524	            carry = p >> 64;
525	            let (d1, b1) = un[j + i].overflowing_sub(p as u64);
526	            let (d2, b2) = d1.overflowing_sub(borrow as u64);
527	            un[j + i] = d2;
528	            borrow = b1 || b2;
529	        }
530	        let (v1_, b1_) = un[j + n].overflowing_sub(carry as u64);
531	        let (v2_, b2_) = v1_.overflowing_sub(borrow as u64);
532	        un[j + n] = v2_;
533	
534	        if b1_ || b2_ {
535	            // The trial digit was one too large despite the correction
536	            // above -- the one case Knuth's proof leaves open. Add the
537	            // divisor back once; the resulting carry exactly cancels the
538	            // deficit just detected, so it's discarded, not propagated.
539	            let mut addcarry = false;
540	            for i in 0..n {
541	                let (s1, c1) = un[j + i].overflowing_add(bn[i]);
542	                let (s2, c2) = s1.overflowing_add(addcarry as u64);
543	                un[j + i] = s2;
544	                addcarry = c1 || c2;
545	            }
546	            un[j + n] = un[j + n].wrapping_add(addcarry as u64);
547	            q[j] = (qhat as u64).wrapping_sub(1);
548	        } else {
549	            q[j] = qhat as u64;
550	        }
551	    }
552	
553	    let remainder = shift_right_bits(&un[..n], shift);
554	    (limbs_trim(q), remainder)
555	}
