561	/// Halve an even number, reading the result off its own word rather than
562	/// dividing. None for odd n. See bits_halve for the real operation; this
563	/// is just its BigUint entry and exit.
564	pub fn halve_even_by_word(n: &BigUint) -> Option<BigUint> {
565	    bits_halve(&word_bits(n)).map(|b| bits_to_value(&b))
566	}
