568	/// n's own bit blocks, packed into 64-bit limbs least-significant first,
569	/// read from its word's characters rather than computed by division.
570	/// Empty for zero.
571	pub(crate) fn word_bits(n: &BigUint) -> alloc::vec::Vec<u64> {
572	    let word = encode_biguint(n);
573	    let c: alloc::vec::Vec<char> = word.chars().collect();
574	    if c.len() == 4 { return alloc::vec::Vec::new(); }
575	    let body = &c[1..c.len() - 3];
576	    let nbits = body.len() / 5;
577	    let mut limbs = alloc::vec::Vec::with_capacity(nbits / 64 + 1);
578	    for (i, cell) in body.chunks(5).enumerate() {
579	        if cell[3] == '⊥' {
580	            let li = i / 64;
581	            while limbs.len() <= li { limbs.push(0); }
582	            limbs[li] |= 1u64 << (i % 64);
583	        }
584	    }
585	    limbs_trim(limbs)
586	}
