588	/// n's own parity, read off the lowest bit of its own limbs rather than a
589	/// remainder. No limbs at all (zero's word) reads as even.
590	fn is_odd_by_word(n: &BigUint) -> bool {
591	    bits_is_odd(&word_bits(n))
592	}
