598	/// Double a number, reading the result off its own word rather than
599	/// multiplying. See bits_double for the real operation.
600	pub fn double_via_word(n: &BigUint) -> BigUint {
601	    bits_to_value(&bits_double(&word_bits(n)))
602	}
