604	/// The one BigUint-exit point every bits_* result passes through: reads
605	/// straight off the limbs' own byte layout (to_u64_digits' own inverse,
606	/// the same "plain memory read, not a computation" discipline
607	/// to_bits_low_first already uses on its way in), rather than building
608	/// the full glyph string those same limbs would produce under encode and
609	/// decoding it back. The two give the identical value -- the word's own
610	/// bits ARE this limb layout, checked bit-for-bit against real binary
611	/// earlier this session -- so building the string was real, measured
612	/// cost (roughly 5 characters allocated and pushed per bit) buying
613	/// nothing the direct read doesn't already give exactly. Every other
614	/// via_word wrapper calls this on its way out, so this was the actual
615	/// cost dominating them, not the arithmetic underneath -- confirmed
616	/// directly: a single call on a 64-limb value went from this being the
617	/// dominant term in a multi-millisecond multiply_via_word call to
618	/// microseconds once fixed.
619	pub(crate) fn bits_to_value(limbs: &[u64]) -> BigUint {
620	    if limbs.is_empty() { return BigUint::zero(); }
621	    let mut bytes = alloc::vec::Vec::with_capacity(limbs.len() * 8);
622	    for &limb in limbs {
623	        bytes.extend_from_slice(&limb.to_le_bytes());
624	    }
625	    BigUint::from_bytes_le(&bytes)
626	}
