647	/// Divide and take the remainder together. See bits_divmod_knuth for the
648	/// real operation -- limb-at-a-time long division, not bit-at-a-time --
649	/// the whole walk runs in limb form and only touches BigUint once, on
650	/// the way out. bits_divmod (bit-at-a-time) stays in the file as a
651	/// cross-check oracle for bits_divmod_knuth's own tests, not on this
652	/// live path anymore. None for m=0.
653	pub fn divmod_via_word(a: &BigUint, m: &BigUint) -> Option<(BigUint, BigUint)> {
654	    if m.is_zero() { return None; }
655	    let (q, r) = bits_divmod_knuth(&word_bits(a), &word_bits(m));
