664	/// The actual limb-at-a-time division, on limbs alone -- the same
665	/// technique any bignum library uses for single-word division, walking
666	/// from the most significant limb down and carrying the running
667	/// remainder into the next one, genuinely limb-at-a-time rather than
668	/// bit-at-a-time. Callers that already hold a's limbs (a hot loop
669	/// testing many small divisors against the same, unchanging a) should
670	/// call this directly rather than divmod_small_via_word, which re-reads
671	/// a's own word on every call -- cheap once, wasteful thousands or
672	/// millions of times over for a value that never changes between calls.
673	pub(crate) fn divmod_small_on_limbs(limbs: &[u64], small: u64) -> (alloc::vec::Vec<u64>, u64) {
674	    let mut q = alloc::vec::Vec::with_capacity(limbs.len());
675	    q.resize(limbs.len(), 0u64);
676	    let mut rem: u128 = 0;
677	    let divisor = small as u128;
678	    for i in (0..limbs.len()).rev() {
679	        let cur = (rem << 64) | limbs[i] as u128;
680	        q[i] = (cur / divisor) as u64;
681	        rem = cur % divisor;
682	    }
683	    (limbs_trim(q), rem as u64)
684	}
