686	/// Divide by a divisor known to fit in one word: reads a's own word once
687	/// (word_bits) and runs the limb-at-a-time division above. divmod_via_word's
688	/// own bits_divmod walks every bit of the dividend and allocates a fresh
689	/// quotient bit vector on every call; that generality is exactly what a
690	/// hot loop trying thousands or millions of small candidate divisors
691	/// cannot afford, the same lesson the GPU BSGS work already drew: replace
692	/// the slow, allocation-heavy path with a fast one computing the identical
693	/// value, not with abandoning word-native arithmetic for the loop. A
694	/// caller running many divisors against the same unchanging a should read
695	/// word_bits(a) once and call divmod_small_on_limbs directly instead of
696	/// this. None for small=0.
697	pub fn divmod_small_via_word(a: &BigUint, small: u64) -> Option<(BigUint, u64)> {
698	    if small == 0 { return None; }
699	    let (q, r) = divmod_small_on_limbs(&word_bits(a), small);
700	    Some((bits_to_value(&q), r))
701	}
