710	/// Add a nonnegative magnitude to a signed value without ever letting
711	/// BigInt run its own +/-: split c into sign and magnitude (both already
712	/// exposed by BigInt itself, not a word computation), settle which
713	/// magnitude is larger via subtract_via_word's own Some/None, and
714	/// reattach the sign that survives. Used by hensel_unbraid's carry
715	/// update, the one place in this file a value can go negative.
716	fn signed_add_via_word(c: &BigInt, m: &BigUint) -> BigInt {
717	    match c.sign() {
718	        num_bigint::Sign::Minus => match subtract_via_word(m, c.magnitude()) {
719	            Some(diff) => BigInt::from_biguint(num_bigint::Sign::Plus, diff),
720	            None => BigInt::from_biguint(num_bigint::Sign::Minus, subtract_via_word(c.magnitude(), m).unwrap()),
721	        },
722	        _ => BigInt::from_biguint(num_bigint::Sign::Plus, add_via_word(c.magnitude(), m)),
723	    }
724	}
