726	/// Halve a signed value known to be even (hensel_unbraid's own invariant:
727	/// c_k is only ever divided once the parity equation has already forced
728	/// it even). The sign passes through untouched; the magnitude halves
729	/// exactly via halve_even_by_word, same as every even halving elsewhere
730	/// in this file.
731	fn halve_exact_signed_via_word(c: &BigInt) -> BigInt {
732	    BigInt::from_biguint(c.sign(), halve_even_by_word(c.magnitude()).unwrap())
733	}
