735	/// Flip a signed value's sign, magnitude untouched. from_biguint normalizes
736	/// a zero magnitude to NoSign on its own, so negating zero stays zero.
737	fn negate_signed(b: &BigInt) -> BigInt {
738	    match b.sign() {
739	        num_bigint::Sign::Minus => BigInt::from_biguint(num_bigint::Sign::Plus, b.magnitude().clone()),
740	        num_bigint::Sign::Plus => BigInt::from_biguint(num_bigint::Sign::Minus, b.magnitude().clone()),
741	        num_bigint::Sign::NoSign => BigInt::from(0),
742	    }
743	}
