745	/// General signed add, a and b each of any sign -- signed_add_via_word only
746	/// ever added a nonnegative magnitude to a signed value (all
747	/// hensel_unbraid needed); modinv_big's extended Euclid needs both sides
748	/// signed. When b >= 0 this is exactly signed_add_via_word. When b < 0,
749	/// a + b is a - |b|: if a is also nonnegative, that's the same ordered-
750	/// subtraction shape subtract_via_word's own Some/None already answers;
751	/// if a is negative too, both magnitudes are moving the same direction and
752	/// just add.
753	pub(crate) fn signed_add_via_word_general(a: &BigInt, b: &BigInt) -> BigInt {
754	    if b.sign() != num_bigint::Sign::Minus {
755	        signed_add_via_word(a, b.magnitude())
756	    } else if a.sign() != num_bigint::Sign::Minus {
757	        match subtract_via_word(a.magnitude(), b.magnitude()) {
758	            Some(diff) => BigInt::from_biguint(num_bigint::Sign::Plus, diff),
759	            None => BigInt::from_biguint(num_bigint::Sign::Minus, subtract_via_word(b.magnitude(), a.magnitude()).unwrap()),
760	        }
761	    } else {
762	        BigInt::from_biguint(num_bigint::Sign::Minus, add_via_word(a.magnitude(), b.magnitude()))
763	    }
764	}
