766	/// General signed subtract: a - b = a + (-b), reusing the general add above.
767	pub(crate) fn signed_subtract_via_word_general(a: &BigInt, b: &BigInt) -> BigInt {
768	    signed_add_via_word_general(a, &negate_signed(b))
769	}
