771	/// General signed multiply: the magnitude is multiply_via_word on the two
772	/// magnitudes; the sign is Minus exactly when the operands' signs differ
773	/// (an XOR on which side is Minus, not a word computation -- sign is
774	/// bookkeeping BigInt already carries, same convention as every signed
775	/// wrapper in this file).
776	pub(crate) fn signed_multiply_via_word(a: &BigInt, b: &BigInt) -> BigInt {
777	    let mag = multiply_via_word(a.magnitude(), b.magnitude());
778	    let neg = (a.sign() == num_bigint::Sign::Minus) != (b.sign() == num_bigint::Sign::Minus);
779	    BigInt::from_biguint(if neg { num_bigint::Sign::Minus } else { num_bigint::Sign::Plus }, mag)
780	}
