782	/// General signed divmod, truncating toward zero -- the quotient's sign is
783	/// Minus exactly when the operands' signs differ, and the remainder takes
784	/// the dividend's own sign, matching BigInt's own Div/Rem exactly (T-
785	/// division): both are read straight off divmod_via_word's unsigned
786	/// quotient and remainder on the magnitudes, which is already a floor
787	/// division on those magnitudes and therefore already the truncation,
788	/// since magnitudes are never negative. None only when b is zero.
789	pub(crate) fn signed_divmod_via_word(a: &BigInt, b: &BigInt) -> Option<(BigInt, BigInt)> {
790	    let (q_mag, r_mag) = divmod_via_word(a.magnitude(), b.magnitude())?;
791	    let q_neg = (a.sign() == num_bigint::Sign::Minus) != (b.sign() == num_bigint::Sign::Minus);
792	    let q = BigInt::from_biguint(if q_neg { num_bigint::Sign::Minus } else { num_bigint::Sign::Plus }, q_mag);
793	    let r = BigInt::from_biguint(a.sign(), r_mag);
794	    Some((q, r))
795	}
