930	/// n as bits, least significant first. `true` is an odd (1) bit. This is
931	/// the root bit-extraction primitive encode_biguint itself builds the word
932	/// from, so it can't read the word back the way word_bits does downstream
933	/// of it -- that would be circular. Instead it reads BigUint's own u64
934	/// limbs directly (to_u64_digits, a plain memory read of the digits BigUint
935	/// already stores, not a computation), the same "don't compute what's
936	/// already sitting there in binary" discipline as every via_word wrapper,
937	/// applied at the one point upstream of the word rather than downstream of
938	/// it.
939	pub(crate) fn to_bits_low_first(n: &BigUint) -> alloc::vec::Vec<bool> {
940	    let limbs = n.to_u64_digits();
941	    let mut bits = alloc::vec::Vec::with_capacity(limbs.len() * 64);
942	    for limb in limbs {
943	        for i in 0..64 {
944	            bits.push((limb >> i) & 1 == 1);
945	        }
946	    }
947	    while let Some(false) = bits.last() { bits.pop(); }
948	    bits
949	}
