124	    #[test]
125	    fn factor_flat_payload_is_the_surviving_dyad() {
126	        // Dissolution: the flat payload has exactly one surviving split/fuse
127	        // pair, the outer containment.
128	        assert_eq!(FACTOR_TOWER_WORD.matches('∈').count(), 1);
129	        assert_eq!(FACTOR_TOWER_WORD.matches('∋').count(), 1);
130	        // Fixation sits before the fuse but after the work: the factor pair is
131	        // fixed, then the enclosing fuse closes.
132	        let fix = FACTOR_TOWER_WORD.find('⊡').unwrap();
133	        let fuse = FACTOR_TOWER_WORD.rfind('∋').unwrap();
134	        assert!(fix < fuse);
135	    }
