1	//! gpu_vox.rs — the vox control-flow closure verdict on the GPU.
2	//!
3	//! One word per thread. Each glyph reduces to a class the verdict needs: a fork
4	//! (in), a fuse (out), a work opcode, or other. The thread rotates to the
5	//! least-balance cut, pairs forks with fuses cyclically from there, and reads
6	//! the verdict: N when nothing forked or a paired region did no work, T when
7	//! every fork pairs and some region did work, B when a fork is left open, F
8	//! when fuses outnumber forks. This is vox::verdict, run on the device and
9	//! checked against the CPU auditor word for word.
10	
11	use alloc::format;
12	use alloc::string::String;
13	use alloc::vec::Vec;
14	use cudarc::driver::{CudaContext, LaunchConfig, PushKernelArg};
15	use cudarc::nvrtc::compile_ptx;
16	
17	const WLEN: usize = 256;   // per-word cap
18	
19	/// Glyph -> class: 1 fork, 2 fuse, 3 work, 0 other.
20	fn code_of(c: char) -> u8 {
21	    use crate::vox::{FSPLIT, FFUSE, AFWD, AREV, CLINK, EVALT, EVALF, ENGAGR, IFIX};
22	    if c == FSPLIT { 1 }
23	    else if c == FFUSE { 2 }
24	    else if c == AFWD || c == AREV || c == CLINK || c == EVALT || c == EVALF || c == ENGAGR || c == IFIX { 3 }
25	    else { 0 }
26	}
27	
28	const KERNEL_SRC: &str = r#"
29	// codes: 1 fork, 2 fuse, 3 work, 0 other. One word per thread. Output verdict
30	// as 0=N, 1=T, 2=F, 3=B.
31	extern "C" __global__ void vox_verdict(
32	    const unsigned char* codes, const unsigned int* lens,
33	    unsigned char* out, unsigned int n)
34	{
35	    unsigned int gid = blockIdx.x * blockDim.x + threadIdx.x;
36	    if (gid >= n) return;
37	    const int WLEN = 256;
38	    unsigned char w[256];
39	    unsigned int L = lens[gid];
40	    if (L > 256) L = 256;
41	    for (unsigned int i=0;i<L;i++) w[i] = codes[gid*WLEN + i];
42	
43	    unsigned int nSplit=0, nFuse=0;
44	    for (unsigned int i=0;i<L;i++){ if (w[i]==1) nSplit++; else if (w[i]==2) nFuse++; }
45	    if (nSplit==0 && nFuse==0) { out[gid]=0; return; }   // N
46	
47	    // least-balance rotation
48	    long long bal=0, least=0; unsigned int start=0;
49	    for (unsigned int i=0;i<L;i++){
50	        bal += (w[i]==1)?1:((w[i]==2)?-1:0);
51	        if (bal < least) { least=bal; start=(i+1)%L; }
52	    }
53	
54	    // cyclic pairing from start
55	    unsigned int stack[256]; int top=0;
56	    unsigned int unFuse=0, pairs=0; unsigned char anyWork=0;
57	    for (unsigned int off=0; off<L; off++){
58	        unsigned int i=(start+off)%L;
59	        if (w[i]==1) { stack[top++]=i; }
60	        else if (w[i]==2) {
61	            if (top>0) {
62	                unsigned int si=stack[--top];
63	                pairs++;
64	                unsigned int len=(i + L - si - 1)%L;   // interior length
65	                for (unsigned int j=0;j<len;j++){ if (w[(si+1+j)%L]==3) { anyWork=1; break; } }
66	            } else { unFuse++; }
67	        }
68	    }
69	    unsigned int unSplit=(unsigned int)top;
70	
71	    unsigned char v;
72	    if (pairs==0 && unSplit==0 && unFuse==0) v=0;      // N
73	    else if (unFuse > unSplit) v=2;                     // F
74	    else if (unSplit > 0) v=3;                          // B
75	    else if (anyWork) v=1;                              // T
76	    else v=0;                                           // N
77	    out[gid]=v;
78	}
79	"#;
80	
81	fn vchar(v: u8) -> char { match v { 1=>'T', 2=>'F', 3=>'B', _=>'N' } }
82	
83	struct Xs(u64);
84	impl Xs { fn n(&mut self)->u64{ let mut x=self.0; x^=x<<13; x^=x>>7; x^=x<<17; self.0=x; x } }
85	
86	/// Run `count` random glyph words on the GPU and the CPU auditor, report the
87	/// first verdict that differs.
88	pub fn verify(count: usize, seed: u64, device: usize) -> String {
89	    use crate::vox::{VINIT, TANCH, AFWD, AREV, IMSCRIB, IFIX, CLINK, EVALT, EVALF, ENGAGR, FSPLIT, FFUSE};
90	    let glyphs: [char; 12] = [VINIT, TANCH, AFWD, AREV, CLINK, EVALT, FSPLIT, FFUSE, IMSCRIB, EVALF, ENGAGR, IFIX];
91	
92	    let ctx = match CudaContext::new(device) { Ok(c)=>c, Err(e)=>return format!("gpu_vox: no CUDA context: {e}") };
93	    let stream = ctx.default_stream();
94	    let ptx = match compile_ptx(KERNEL_SRC) { Ok(p)=>p, Err(e)=>return format!("gpu_vox: NVRTC: {e}") };
95	    let module = match ctx.load_module(ptx) { Ok(m)=>m, Err(e)=>return format!("gpu_vox: module: {e}") };
96	    let func = match module.load_function("vox_verdict") { Ok(f)=>f, Err(e)=>return format!("gpu_vox: load: {e}") };
97	
98	    let mut rng = Xs(seed ^ 0xA5A5_5A5A_1234_9876);
99	    let n = count;
100	    let mut codes = alloc::vec![0u8; n * WLEN];
101	    let mut lens = alloc::vec![0u32; n];
102	    let mut words: Vec<Vec<char>> = Vec::with_capacity(n);
103	    for g in 0..n {
104	        let len = 2 + (rng.n() % 60) as usize;   // 2..62
105	        let mut w = Vec::with_capacity(len);
106	        for j in 0..len {
107	            let c = glyphs[(rng.n() % 12) as usize];
108	            codes[g*WLEN + j] = code_of(c);
109	            w.push(c);
110	        }
111	        lens[g] = len as u32;
112	        words.push(w);
113	    }
114	
115	    let d_codes = match stream.clone_htod(&codes) { Ok(d)=>d, Err(e)=>return format!("gpu_vox: htod codes: {e}") };
116	    let d_lens = match stream.clone_htod(&lens) { Ok(d)=>d, Err(e)=>return format!("gpu_vox: htod lens: {e}") };
117	    let mut d_out = match stream.alloc_zeros::<u8>(n) { Ok(d)=>d, Err(e)=>return format!("gpu_vox: alloc: {e}") };
118	
119	    let block: u32 = 128;
120	    let grid = ((n as u32) + block - 1) / block;
121	    let cfg = LaunchConfig { grid_dim:(grid,1,1), block_dim:(block,1,1), shared_mem_bytes:0 };
122	    let nn = n as u32;
123	    let mut b = stream.launch_builder(&func);
124	    b.arg(&d_codes); b.arg(&d_lens); b.arg(&mut d_out); b.arg(&nn);
125	    if let Err(e) = unsafe { b.launch(cfg) } { return format!("gpu_vox: launch: {e}"); }
126	    let g_out = match stream.clone_dtoh(&d_out) { Ok(v)=>v, Err(e)=>return format!("gpu_vox: dtoh: {e}") };
127	
128	    let mut mism = 0usize; let mut first = String::new();
129	    for g in 0..n {
130	        let cpu = crate::vox::verdict(&words[g]);
131	        let gpu = vchar(g_out[g]);
132	        if cpu != gpu {
133	            mism += 1;
134	            if first.is_empty() {
135	                let s: String = words[g].iter().collect();
136	                first = format!("  first mismatch: word '{}'  CPU={} GPU={}", s, cpu, gpu);
137	            }
138	        }
139	    }
140	    if mism == 0 {
141	        format!("gpu_vox verify: {} words, GPU verdict == CPU vox::verdict on every one", n)
142	    } else {
143	        format!("gpu_vox verify: {}/{} words DIVERGED\n{}", mism, n, first)
144	    }
145	}
146	
147	/// Verdict one glyph word on the device, with the CPU verdict beside it.
148	pub fn run(word: &str, device: usize) -> String {
149	    let w: Vec<char> = word.chars().filter(|c| !c.is_whitespace()).collect();
150	    if w.is_empty() { return "gpu_vox verdict <glyph-word>".into(); }
151	    if w.len() > WLEN { return format!("gpu_vox: word longer than {} marks", WLEN); }
152	
153	    let ctx = match CudaContext::new(device) { Ok(c)=>c, Err(e)=>return format!("gpu_vox: no CUDA context: {e}") };
154	    let stream = ctx.default_stream();
155	    let ptx = match compile_ptx(KERNEL_SRC) { Ok(p)=>p, Err(e)=>return format!("gpu_vox: NVRTC: {e}") };
156	    let module = match ctx.load_module(ptx) { Ok(m)=>m, Err(e)=>return format!("gpu_vox: module: {e}") };
157	    let func = match module.load_function("vox_verdict") { Ok(f)=>f, Err(e)=>return format!("gpu_vox: load: {e}") };
158	
159	    let mut codes = alloc::vec![0u8; WLEN];
160	    for (i,&c) in w.iter().enumerate() { codes[i] = code_of(c); }
161	    let lens = alloc::vec![w.len() as u32];
162	    let d_codes = match stream.clone_htod(&codes) { Ok(d)=>d, Err(e)=>return format!("gpu_vox: htod: {e}") };
163	    let d_lens = match stream.clone_htod(&lens) { Ok(d)=>d, Err(e)=>return format!("gpu_vox: htod: {e}") };
164	    let mut d_out = match stream.alloc_zeros::<u8>(1) { Ok(d)=>d, Err(e)=>return format!("gpu_vox: alloc: {e}") };
165	    let cfg = LaunchConfig { grid_dim:(1,1,1), block_dim:(1,1,1), shared_mem_bytes:0 };
166	    let nn = 1u32;
167	    let mut b = stream.launch_builder(&func);
168	    b.arg(&d_codes); b.arg(&d_lens); b.arg(&mut d_out); b.arg(&nn);
169	    if let Err(e) = unsafe { b.launch(cfg) } { return format!("gpu_vox: launch: {e}"); }
170	    let g_out = match stream.clone_dtoh(&d_out) { Ok(v)=>v, Err(e)=>return format!("gpu_vox: dtoh: {e}") };
171	
172	    let gpu = vchar(g_out[0]);
173	    let cpu = crate::vox::verdict(&w);
174	    format!("gpu_vox verdict on device: {}   (CPU vox::verdict: {}, matches: {})", gpu, cpu, gpu == cpu)
175	}
