            return "N".to_string();
        }
        if self.big_t && self.big_f && self.small_t && self.small_f {
            return "A".to_string();
        }
        let mut s = String::new();
        if self.big_t { s.push('T'); }
        if self.big_f { s.push('F'); }
        if self.small_t { s.push('t'); }
        if self.small_f { s.push('f'); }
        s
